import json
from pathlib import Path

ROOT = Path(__file__).parent
cases, rubrics = [], []

def add(family, number, request, invariants, qa, protected=(), failures=()):
    prefix = dict(short_edits='S',document_editing='D',conversation_updates='C',voice='V',meaning='M',structured_content='F')[family]
    case_id = f'{prefix}{number:02d}'
    cases.append(dict(id=case_id, family=family, split='development' if number <= 5 else 'heldout', pilot=number <= 2, request=request))
    rubrics.append(dict(id=case_id, semantic_invariants=invariants, comprehension_questions=[dict(question=q, expected_answer=a) for q,a in qa], protected_substrings=list(protected), failure_criteria=list(failures)))

