add('voice',2, 'Polish only if needed, preserving the writer’s quiet voice: "I liked the small room at the back. Nobody hurried us. We stayed until the rain stopped."', ['Quiet, concrete first-person voice.', 'Small back room; unhurried stay until rain stopped.', 'Unchanged is acceptable.'], [('Why did they leave when they did?', 'They stayed until the rain stopped; no further motive established.')], failures=['Adds ornate imagery or invented emotions.'])
add('voice',3, 'Rewrite for a friendly but firm customer-service voice: "You failed to return the rented projector on time. Therefore, a $25 late fee has been assessed. If you believe our return record is incorrect, send your drop-off receipt by Friday."', ['$25 fee assessed for late return.', 'Challenge via receipt by Friday.', 'No automatic refund promise.'], [('How can the customer dispute the record?', 'Send the drop-off receipt by Friday.')], failures=['Removes fee to sound nicer.', 'Sounds accusatory or patronizing.'])
add('voice',4, 'Keep the dry humor, remove only clutter: "The new office kettle is, after an unnecessarily elaborate procurement journey, here. It boils water. We have tested this revolutionary capability. Please empty it before the weekend."', ['Kettle arrived and tested.', 'Empty before weekend.', 'Retain understated joke.'], [('What action is requested?', 'Empty the kettle before the weekend.')], failures=['Turns it into a formal procurement memo.', 'Adds jokes that obscure instruction.'])
add('voice',5, 'Write a calm correction for a school newsletter. Facts: Yesterday’s newsletter said sports day is Wednesday; correct day is Thursday, May 16. Start time remains 9 a.m. Keep it plain, with one brief apology, no defensive explanation.', ['Correction to Thursday May 16.', '9 a.m. unchanged.', 'One brief apology.'], [('When does sports day begin?', 'Thursday May 16 at 9 a.m.')], failures=['Invents reason for error.', 'Over-apologizes or buries correction.'])
add('voice',6, 'Edit this note from a grieving friend without making it cheerful or adding beliefs: "I don’t know the right thing to say. I loved how your dad always made room at the table. I can bring dinner Thursday, if that would help."', ['Specific memory of dad retained.', 'Conditional Thursday dinner offer.', 'No spiritual beliefs or positivity imposed.', 'Minimal or no change valid.'], [('What concrete help is offered?', 'Dinner Thursday, if helpful.')], failures=['Adds "everything happens for a reason" or invented memories.', 'Turns offer into a confirmed visit.'])
add('voice',7, 'Rewrite a museum label for curious 10-year-olds without baby talk: "This vessel facilitated the preservation of perishable provisions through evaporative cooling." Facts: Water seeped through tiny pores in the clay. As it evaporated, it carried heat away. Food inside stayed cooler. No electricity was used.', ['Evaporation carries heat away.', 'Porous clay and cooler food; no electricity.', 'Explain unfamiliar mechanism in accessible language.'], [('How did the pot cool food?', 'Water seeped through clay pores and evaporated, carrying away heat.')], failures=['Says the pot creates cold or refrigerates to a specified temperature.', 'Uses baby talk.'])
add('voice',8, 'Write a confident design critique using only this observation: Three primary buttons use identical color and size, so testers repeatedly chose Cancel instead of Save. Suggest a concrete visual change. Do not hedge every sentence or insult the designer.', ['Observed tester error linked to equal visual emphasis.', 'Concrete differentiation recommendation.', 'No unsupported universal claim.'], [('What observed problem should the redesign address?', 'Testers confused Cancel with Save because controls looked equally primary.')], failures=['Vague "improve hierarchy" with no action.', 'Claims all users failed or attacks competence.'])
