assert len(cases)==60
assert len({c['id'] for c in cases})==60
assert sum(c['pilot'] for c in cases)==12
assert sum(c['split']=='heldout' for c in cases)==30
for name in {c['family'] for c in cases}:
    assert sum(c['family']==name for c in cases)==10
for doc in (DOC1,DOC2,DOC3,DOC4):
    assert len(doc.split())>=500, len(doc.split())
assert {r['id'] for r in rubrics}=={c['id'] for c in cases}
for case, rubric in zip(cases,rubrics):
    for protected in rubric['protected_substrings']:
        assert protected in case['request'], (case['id'], protected)
ROOT.joinpath('cases.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
rubric_map = {r['id']:dict(invariants=r['semantic_invariants'],questions=[dict(question=q['question'],answer=q['expected_answer']) for q in r['comprehension_questions']],protected=r['protected_substrings'],hard_failures=r['failure_criteria']) for r in rubrics}
ROOT.joinpath('rubric.json').write_text(json.dumps(rubric_map,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'cases':len(cases),'rubrics':len(rubrics),'pilot':12,'development':30,'heldout':30,'long_document_words':[len(d.split()) for d in (DOC1,DOC2,DOC3,DOC4)]}))
